import os, tempfile, sys, time, random, sqlite3
sys.path.insert(0, "src")
from forgetting_evidence.requests import RequestStore

tmp = tempfile.mkdtemp()
db = os.path.join(tmp, "e.db")
s = RequestStore(db)

def rebuild():
    global s
    s = RequestStore(db)

# Model: track per batch all items ever reported per cursor lineage
reported = {}   # batch_id -> list of request_ids ever returned
cursor_birth = {}  # cursor -> (batch, count_at_issue)

def do_batch(tenant, cursor=None, limit=None):
    r = s.reconcile_batch(tenant, cursor, limit) if limit is not None else s.reconcile_batch(tenant, cursor)
    bid = r["batch_id"]
    reported.setdefault(bid, [])
    for it in r["items"]:
        if it["request_id"] in reported[bid]:
            print("!!! DUPLICATE REPORT in batch", bid, "rid", it["request_id"])
            print("    prior:", reported[bid])
            print("    call items:", [x["request_id"] for x in r["items"]], "cursor:", cursor)
        reported[bid].append(it["request_id"])
    if r["next_cursor"]:
        cursor_birth[r["next_cursor"]] = (bid, len(reported[bid]))
    return r

random.seed(42)
nextid = 0
live = []  # (rid, token, expiry_lease)
for step in range(300):
    op = random.random()
    if op < 0.30:
        rid = s.submit("t", f"sub{nextid}", ["email", f"x{nextid%3}"], f"k{nextid}")["request_id"]
        nextid += 1
    elif op < 0.45:
        c = s.claim_next("t", "w", 1)
        if c: live.append(c["request_id"])
    elif op < 0.50:
        time.sleep(0.05)
    elif op < 0.55:
        # single reconcile random request
        try:
            with sqlite3.connect(db) as raw:
                row = raw.execute("SELECT request_id FROM requests WHERE tenant_id='t' ORDER BY RANDOM() LIMIT 1").fetchone()
            if row: s.reconcile_execution("t", row[0])
        except Exception as e:
            pass
    elif op < 0.95:
        # batch: sometimes no cursor, sometimes replay an old cursor
        cur = None
        if cursor_birth and random.random() < 0.5:
            cur = random.choice(list(cursor_birth))
        try:
            do_batch("t", cur, limit=random.choice([1,2,3,5]))
        except Exception as e:
            print("exc:", type(e).__name__, e)
    else:
        rebuild()

# final: replay every cursor ever issued, multiple times
for cur in list(cursor_birth):
    for _ in range(2):
        try:
            r = do_batch("t", cur, limit=2)
        except Exception as e:
            print("replay exc:", type(e).__name__, e)
# fresh sweeps
do_batch("t"); do_batch("t")
print("done. batches:", len(reported))
